schema:
CREATE TABLE vendor (v_id INTEGER NOT NULL PRIMARY KEY, v_name TEXT NOT NULL);

CREATE TABLE shipment (sh_id INTEGER NOT NULL PRIMARY KEY, status TEXT NOT NULL);

CREATE TABLE package_item (pi_sh_id INTEGER NOT NULL, item_no INTEGER NOT NULL, vendor_id INTEGER NOT NULL, expected_date DATE NOT NULL, received_date DATE NOT NULL, PRIMARY KEY (pi_sh_id, item_no), FOREIGN KEY (pi_sh_id) REFERENCES shipment (sh_id), FOREIGN KEY (vendor_id) REFERENCES vendor (v_id));
